    ["<Assistant_Title1>Self-Cultivation of Acting</>\n<Assistant_Title2>Achievement Category: </>TRPG-Order World\n<Assistant_Title2>Unlock Condition: </>Unlock TRPG talents for the first time"] = "<Assistant_Title1>Самосовершенствование актерского мастерства</>\n<Assistant_Title2>Категория достижений: </>TRPG-Мировой порядок\n<Assistant_Title2>Условие разблокировки: </>Впервые разблокировать таланты TRPG",
